const express = require('express');
const path = require('path');
const Download = require('../models/Download');

const router = express.Router();

// PDF Download Route (valid for 24 hours, multiple times)
router.get('/:token', async (req, res) => {
  const { token } = req.params;

  try {
    const entry = await Download.findOne({ token });

    if (!entry) {
      return res.status(404).json({ error: 'Invalid download token' });
    }

    // Check if token expired
    if (entry.expiresAt < new Date()) {
      return res.status(403).json({ error: 'Download link expired' });
    }

    // Serve the PDF (multiple downloads allowed until expiry)
    const filePath = path.join(__dirname, '../assets/resume.pdf');
    res.download(filePath, 'resume.pdf');
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

module.exports = router;
